app.post('/api/agent/test', async (req,res) => {
  const session = await requireUser(req,res); if (!session) return;
  try {
    const input = z.object({keys:z.array(z.object({key:z.string().min(20).max(300),model:z.string().min(1).max(100),task:z.enum(['all','diagnosis','repair','file','image','video','text','workflow']).optional()})).min(1).max(8)}).parse(req.body);
    const results = [];
    for (const [keyIndex,candidate] of input.keys.entries()) {
      const started = Date.now();
      try {
        const ai = new GoogleGenerativeAI(candidate.key);
        const model = ai.getGenerativeModel({model:candidate.model, generationConfig:{maxOutputTokens:32,temperature:0}});
        const result = await model.generateContent('Reply with exactly: POTHUB_OK');
        const text = result.response.text().trim();
        results.push({keyIndex,model:candidate.model,ok:/POTHUB_OK/i.test(text),latencyMs:Date.now()-started,error:null});
      } catch (e) { results.push({keyIndex,model:candidate.model,ok:false,latencyMs:Date.now()-started,error:String(e?.message||'Provider test failed').slice(0,180)}); }
    }
    const usable = results.filter(x=>x.ok).sort((a,b)=>a.latencyMs-b.latencyMs);
    res.json({results,best:usable[0]||null,policy:'Keys are used only for this test request and are not stored by this endpoint.'});
  } catch(e) { err(res,e,e instanceof z.ZodError?422:400); }
});
