app.post('/api/vercel/connect/start',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{if(!process.env.VERCEL_CLIENT_ID||!process.env.VERCEL_CLIENT_SECRET)throw Error('Vercel OAuth is not configured. Set VERCEL_CLIENT_ID and VERCEL_CLIENT_SECRET on the server.');if(!databaseReady)throw Error('Firebase Firestore is required to securely store Vercel connections.');const redirectUri=process.env.VERCEL_REDIRECT_URI||`${origin(req)}/api/auth/vercel/callback`;const {sealData}=await import('@hapi/iron');const nonce=crypto.randomBytes(24).toString('hex');const state=await sealData({githubId:String(s.user.id),nonce,native:!!req.body.native,createdAt:Date.now()},{password:process.env.SESSION_SECRET,ttl:600000});const stateSaved=await db.from('vercel_oauth_states').insert({nonce_hash:crypto.createHash('sha256').update(nonce).digest('hex'),github_id:String(s.user.id),expires_at:new Date(Date.now()+600000).toISOString()});if(stateSaved.error)throw Error('Could not create a one-time Vercel authorization state. Try again.');const u=new URL('https://vercel.com/oauth/authorize');u.searchParams.set('client_id',process.env.VERCEL_CLIENT_ID);u.searchParams.set('redirect_uri',redirectUri);u.searchParams.set('response_type','code');if(process.env.VERCEL_OAUTH_SCOPES)u.searchParams.set('scope',process.env.VERCEL_OAUTH_SCOPES);u.searchParams.set('state',state);res.json({url:u.toString()})}catch(e){err(res,e)}});
