app.post('/api/github/commit-fix',async(req,res)=>{const s=await requireUser(req,res);if(!s)return;try{const i=z.object({owner:z.string().min(1),repo:z.string().min(1),baseBranch:z.string().min(1),commitMessage:z.string().min(4).max(160),files:z.array(z.object({path:z.string().min(1).max(240),content:z.string().max(90000)})).min(1).max(8)}).parse(req.body);for(const f of i.files)if(f.path.startsWith('/')||f.path.split('/').includes('..')||f.path.toLowerCase().includes('.env')||f.path.toLowerCase().includes('secret'))throw Error(`Blocked potentially sensitive or unsafe path: ${f.path}`);const branch=`pothub/repair-${new Date().toISOString().slice(0,10)}-${crypto.randomBytes(3).toString('hex')}`,base=await gh(s,`/repos/${i.owner}/${i.repo}/git/ref/heads/${encodeURIComponent(i.baseBranch)}`),parent=await gh(s,`/repos/${i.owner}/${i.repo}/git/commits/${base.object.sha}`),items=[];for(const f of i.files){const b=await gh(s,`/repos/${i.owner}/${i.repo}/git/blobs`,{method:'POST',body:JSON.stringify({content:f.content,encoding:'utf-8'})});items.push({path:f.path,mode:'100644',type:'blob',sha:b.sha})}const tree=await gh(s,`/repos/${i.owner}/${i.repo}/git/trees`,{method:'POST',body:JSON.stringify({base_tree:parent.tree.sha,tree:items})}),commit=await gh(s,`/repos/${i.owner}/${i.repo}/git/commits`,{method:'POST',body:JSON.stringify({message:i.commitMessage,tree:tree.sha,parents:[base.object.sha]})});await gh(s,`/repos/${i.owner}/${i.repo}/git/refs`,{method:'POST',body:JSON.stringify({ref:`refs/heads/${branch}`,sha:commit.sha})});res.json({ok:true,branch,commitSha:commit.sha,commitUrl:`https://github.com/${i.owner}/${i.repo}/commit/${commit.sha}`,branchUrl:`https://github.com/${i.owner}/${i.repo}/tree/${encodeURIComponent(branch)}`,files:i.files.map(f=>f.path),note:'Review and run checks before merging.'})}catch(e){err(res,e,e instanceof z.ZodError?422:400)}});
async function sendPushToUser(githubId,notification){
 if(!databaseReady)return;const {data:subs,error}=await db.from('notification_subscriptions').select('*').eq('github_id',String(githubId));if(error||!subs?.length)return;
 for(const sub of subs){try{if(sub.kind==='web'&&sub.subscription&&process.env.VAPID_PUBLIC_KEY&&process.env.VAPID_PRIVATE_KEY){const wp=(await import('web-push')).default;wp.setVapidDetails(process.env.VAPID_SUBJECT||'mailto:admin@example.com',process.env.VAPID_PUBLIC_KEY,process.env.VAPID_PRIVATE_KEY);await wp.sendNotification(sub.subscription,JSON.stringify({title:notification.title,body:notification.body,url:notification.url||'/',tag:notification.tag||notification.id||notification.title}))}else if(sub.kind==='android'&&process.env.FIREBASE_SERVICE_ACCOUNT_JSON){const admin=await import('firebase-admin');if(!admin.default.apps.length){const credential=admin.default.credential.cert(JSON.parse(process.env.FIREBASE_SERVICE_ACCOUNT_JSON));admin.default.initializeApp({credential})}await admin.default.messaging().send({token:sub.endpoint.slice(4),notification:{title:notification.title,body:notification.body},data:{url:notification.url||'/'}})}}catch(e){console.warn('Push delivery failed:',e?.code||e?.message||'unknown');if(String(e?.statusCode)==='404'||String(e?.statusCode)==='410')await db.from('notification_subscriptions').delete().eq('endpoint',sub.endpoint)}}
}
